/// <summary>
/// The <c>AVARUMAgreementLineQty_Extension</c> class
/// </summary>
/// <remarks>
/// Modified for unit recalculation
/// </remarks>
[ExtensionOf(tableStr(AgreementLineQuantityCommitment))]
final class AVARUMAgreementLineQty_Extension
{
}

Method.Source:
/// <summary>
/// Specifies when a field is modified on a <c>AgreementLine</c> record.
/// </summary>
/// <param name="_fieldId">
/// The field ID that has been modified.
/// </param>
public void modifiedField(FieldId _fieldId)
{
    inventDim inventDim;

    next modifiedField(_fieldId);

    if (this.agreementModuleType() == ModuleSalesPurch::Sales)
    {
        switch (_fieldId)
        {
            case fieldNum(AgreementLineQuantityCommitment, ProductUnitOfMeasure):
                if (this.AVARUMPriceUnitId != this.inventUnitId())
                {
                    inventDim = this.inventDim();
                    inventDim.ConfigId = this.inventDim().configId;

                    if (inventDim.ConfigId)
                    {
                        inventDim = InventDim::findOrCreate(inventDim);
                    }

                    AVARUMUnitConversionItem conversion = UnitOfMeasureConversion::getUnitConversion_AVA
                    (
                        this.ItemId,
                        inventDim.inventDimId,
                        this.ProductUnitOfMeasure,
                        this.CommitedQuantity,
                        this.AVARUMPriceUnitID
                    );

                    this.AVARUMUnitConvertFactor = conversion.paramFactor();
                    this.AVARUMUnitConversionText = conversion.paramText();
                }
        }
    }
}

/// <summary>
/// Calculates the net amount for the current <c>AgreementLineQuantityCommitment</c> record.
/// </summary>
/// <returns>
/// The net amount calculated based on quantity, unit price, and discounts.
/// </returns>
public LineAmount lineAmount()
{
    LineAmount lineAmount;

    lineAmount = next lineAmount();

    if (this.isQuantityBased() && this.AVARUMUnitConvertFactor > 1 && this.PricePerUnit && this.agreementModuleType()==ModuleSalesPurch::Sales)
    {
        lineAmount = PriceDisc::price2Amount
        (
            this.PricePerUnit,
            this.PriceUnit,
            this.LineDiscountAmount,
            this.CommitedQuantity*this.AVARUMUnitConvertFactor,
            this.CommitedQuantity*this.AVARUMUnitConvertFactor,
            0,
            this.LineDiscountPercent,
            this.agreementHeader().Currency,
            0
        );
    }

    return lineAmount;
}

/// <summary>
/// Gets the  unit for the item.
/// </summary>
/// <returns>
/// The  unit for the item.
/// </returns>
public display UnitIDBase inventUnitId()
{
    return this.inventTable().salesUnitId();
}
